import os,glob,re
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

from collections import Counter
def transform(g):
    h,w=len(g),len(g[0])
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    out=[[bg]*w for _ in range(h)]
    def comps(cells):
        cells=set(cells); seen=set(); res=[]
        for c in cells:
            if c in seen: continue
            st=[c]; seen.add(c); comp=[]
            while st:
                r,cc=st.pop(); comp.append((r,cc))
                for dr in(-1,0,1):
                    for dc in(-1,0,1):
                        n=(r+dr,cc+dc)
                        if n in cells and n not in seen: seen.add(n); st.append(n)
            res.append(comp)
        return res
    for col in set(x for r in g for x in r)-{bg}:
        cells=[(r,c) for r in range(h) for c in range(w) if g[r][c]==col]
        for comp in comps(cells):
            rs=[r for r,c in comp]; cs=[c for r,c in comp]
            r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
            area=(r1-r0+1)*(c1-c0+1)
            if area>=8 and len(comp)/area>=0.6:
                for r in range(r0,r1+1):
                    for c in range(c0,c1+1): out[r][c]=col
    return out
f=transform
